def _stops(name):
    """the colour stops of a map; NAME_r (or, for a map whose own name ends in _r, the name without it) is the map reversed."""
    if name in STOPS:
        return STOPS[name]
    if name.endswith("_r") and name[:-2] in STOPS:
        return STOPS[name[:-2]][::-1]
    if name + "_r" in STOPS:
        return STOPS[name + "_r"][::-1]
    raise KeyError(f"unknown colour map {name!r}; known: {names()} (and each reversed: NAME_r)")


def known(name):
    try:
        _stops(name)
        return True
    except KeyError:
        return False


def lut(name="viridis", n=256):
    """(n, 3) uint8 lookup table."""
    s = np.array(_stops(name), dtype=np.float64)
    x = np.linspace(0, 1, len(s))
    xi = np.linspace(0, 1, n)
    return np.stack([np.interp(xi, x, s[:, c]) for c in range(3)], axis=1).round().astype(np.uint8)


def names():
    return list(STOPS)
